  builder_.add_total_lap_dist(total_lap_dist);
  builder_.add_end_et(end_et);
  builder_.add_current_et(current_et);
  builder_.add_vehicles(vehicles);
  builder_.add_lmu(lmu);
  builder_.add_wind(wind);
  builder_.add_plr_file_name(plr_file_name);
  builder_.add_player_name(player_name);
  builder_.add_num_vehicles(num_vehicles);
  builder_.add_max_laps(max_laps);
  builder_.add_session(session);
