inline FullScoringSessionT::FullScoringSessionT(const FullScoringSessionT &o)
      : track_name(o.track_name),
        session(o.session),
        current_et(o.current_et),
        end_et(o.end_et),
        max_laps(o.max_laps),
        total_lap_dist(o.total_lap_dist),
        num_vehicles(o.num_vehicles),
        game_phase(o.game_phase),
        yellow_flag_state(o.yellow_flag_state),
        sector_flag_0(o.sector_flag_0),
        sector_flag_1(o.sector_flag_1),
        sector_flag_2(o.sector_flag_2),
        start_light(o.start_light),
        num_red_lights(o.num_red_lights),
        in_realtime(o.in_realtime),
        player_name(o.player_name),
        plr_file_name(o.plr_file_name),
        dark_cloud(o.dark_cloud),
        raining(o.raining),
        ambient_temp(o.ambient_temp),
        track_temp(o.track_temp),
        wind((o.wind) ? new isimotor::fbs::Vec3(*o.wind) : nullptr),
        min_path_wetness(o.min_path_wetness),
        max_path_wetness(o.max_path_wetness),
        avg_path_wetness(o.avg_path_wetness),
        lmu((o.lmu) ? new isimotor::fbs::LmuScoringSessionT(*o.lmu) : nullptr) {
  vehicles.reserve(o.vehicles.size());
  for (const auto &vehicles_ : o.vehicles) { vehicles.emplace_back((vehicles_) ? new isimotor::fbs::VehicleScoringT(*vehicles_) : nullptr); }
}

